<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">阴影生成</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="shadow-preview"><view class="shadow-box" :style="{ boxShadow: shadowCss, backgroundColor: '#fff' }"></view></view><view class="shadow-code">{{ shadowCss }}</view><view class="shadow-ctrls"><view class="ctrl-row"><text class="ctrl-l">横向偏移</text><slider class="ctrl-s" :value="offsetX" min="-50" max="50" @change="offsetX=$event.detail.value;update()" block-size="16"/></view><view class="ctrl-row"><text class="ctrl-l">纵向偏移</text><slider class="ctrl-s" :value="offsetY" min="-50" max="50" @change="offsetY=$event.detail.value;update()" block-size="16"/></view><view class="ctrl-row"><text class="ctrl-l">模糊半径</text><slider class="ctrl-s" :value="blur" min="0" max="100" @change="blur=$event.detail.value;update()" block-size="16"/></view><view class="ctrl-row"><text class="ctrl-l">扩展半径</text><slider class="ctrl-s" :value="spread" min="-20" max="50" @change="spread=$event.detail.value;update()" block-size="16"/></view></view><view class="copy-btn" @click="copyCode"><text>复制CSS</text></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const offsetX = ref(4); const offsetY = ref(4); const blur = ref(10); const spread = ref(0)
const shadowCss = computed(function() { return offsetX.value + "px " + offsetY.value + "px " + blur.value + "px " + spread.value + "px rgba(0,0,0,0.2)" })
function update() {}
function copyCode() { uni.setClipboardData({ data: shadowCss.value, success: function() { uni.showToast({ title: "已复制", icon: "success" }) } }) }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#636e72,#2d3436);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.shadow-preview{height:300rpx;display:flex;align-items:center;justify-content:center;background:#fff;border-radius:20rpx;margin-bottom:24rpx}.shadow-box{width:200rpx;height:200rpx;border-radius:20rpx}.shadow-code{background:#fff;border-radius:16rpx;padding:20rpx;font-size:24rpx;font-family:monospace;margin-bottom:24rpx;word-break:break-all}.shadow-ctrls{background:#fff;border-radius:20rpx;padding:16rpx;margin-bottom:24rpx}.ctrl-row{display:flex;align-items:center;padding:12rpx 0}.ctrl-l{font-size:24rpx;color:#666;width:160rpx}.ctrl-s{flex:1}.copy-btn{background:linear-gradient(135deg,#636e72,#2d3436);border-radius:16rpx;padding:24rpx;text-align:center}.copy-btn text{font-size:30rpx;color:#fff;font-weight:600}</style>